# 3D City Builder Game with Traffic

Here's a complete, self-contained HTML page for a Three.js city builder game where you can place buildings and drive through your city with traffic:

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>City Builder Game</title>
    <style>
        body {
            margin: 0;
            overflow: hidden;
            font-family: Arial, sans-serif;
        }
        #ui {
            position: absolute;
            top: 10px;
            left: 10px;
            background: rgba(0,0,0,0.5);
            color: white;
            padding: 10px;
            border-radius: 5px;
            z-index: 100;
        }
        #building-selector {
            position: absolute;
            bottom: 10px;
            left: 50%;
            transform: translateX(-50%);
            background: rgba(0,0,0,0.5);
            padding: 10px;
            border-radius: 5px;
            display: flex;
            gap: 10px;
            z-index: 100;
        }
        .building-btn {
            padding: 8px 15px;
            background: #444;
            color: white;
            border: none;
            border-radius: 4px;
            cursor: pointer;
        }
        .building-btn:hover {
            background: #666;
        }
        .building-btn.active {
            background: #0078ff;
        }
        #help {
            position: absolute;
            top: 10px;
            right: 10px;
            background: rgba(0,0,0,0.5);
            color: white;
            padding: 10px;
            border-radius: 5px;
            max-width: 250px;
            z-index: 100;
        }
    </style>
</head>
<body>
    <div id="ui">
        <div>Buildings Placed: <span id="building-count">0</span></div>
        <div>Current Mode: <span id="current-mode">Building</span></div>
    </div>

    <div id="building-selector">
        <button class="building-btn" data-type="small">Small Building</button>
        <button class="building-btn" data-type="medium">Medium Building</button>
        <button class="building-btn" data-type="large">Large Building</button>
        <button class="building-btn" data-type="skyscraper">Skyscraper</button>
        <button class="building-btn" data-type="house">House</button>
        <button class="building-btn" id="drive-btn">Drive Mode</button>
    </div>

    <div id="help">
        <h3>Controls:</h3>
        <p><strong>Building Mode:</strong><br>
        - Click to place buildings<br>
        - Scroll to rotate building</p>
        <p><strong>Drive Mode:</strong><br>
        - WASD to drive<br>
        - Mouse to look around</p>
    </div>

    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/build/three.min.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/examples/js/controls/PointerLockControls.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/examples/js/loaders/GLTFLoader.js"></script>
    <script>
        // Scene setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB); // Sky blue

        // Camera
        const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.set(0, 10, 20);

        // Renderer
        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0x404040);
        scene.add(ambientLight);

        const directionalLight = new THREE.DirectionalLight(0xffffff, 0.8);
        directionalLight.position.set(50, 100, 50);
        directionalLight.castShadow = true;
        directionalLight.shadow.mapSize.width = 2048;
        directionalLight.shadow.mapSize.height = 2048;
        directionalLight.shadow.camera.near = 0.5;
        directionalLight.shadow.camera.far = 500;
        directionalLight.shadow.camera.left = -100;
        directionalLight.shadow.camera.right = 100;
        directionalLight.shadow.camera.top = 100;
        directionalLight.shadow.camera.bottom = -100;
        scene.add(directionalLight);

        // Ground
        const groundGeometry = new THREE.PlaneGeometry(200, 200);
        const groundMaterial = new THREE.MeshStandardMaterial({ 
            color: 0x3a5f0b,
            roughness: 0.8,
            metalness: 0.2
        });
        const ground = new THREE.Mesh(groundGeometry, groundMaterial);
        ground.rotation.x = -Math.PI / 2;
        ground.receiveShadow = true;
        scene.add(ground);

        // Grid helper
        const gridHelper = new THREE.GridHelper(200, 20, 0x555555, 0x333333);
        scene.add(gridHelper);

        // Roads
        const roadMaterial = new THREE.MeshStandardMaterial({ color: 0x333333 });
        const roads = [];

        // Main roads
        const mainRoadWidth = 4;
        const mainRoadLength = 200;

        // Horizontal road
        const horizontalRoadGeometry = new THREE.BoxGeometry(mainRoadLength, 0.1, mainRoadWidth);
        const horizontalRoad = new THREE.Mesh(horizontalRoadGeometry, roadMaterial);
        horizontalRoad.position.set(0, 0.01, 0);
        horizontalRoad.receiveShadow = true;
        scene.add(horizontalRoad);
        roads.push(horizontalRoad);

        // Vertical road
        const verticalRoadGeometry = new THREE.BoxGeometry(mainRoadWidth, 0.1, mainRoadLength);
        const verticalRoad = new THREE.Mesh(verticalRoadGeometry, roadMaterial);
        verticalRoad.position.set(0, 0.01, 0);
        verticalRoad.receiveShadow = true;
        scene.add(verticalRoad);
        roads.push(verticalRoad);

        // Side roads
        const sideRoadWidth = 2;
        const sideRoadLength = 50;

        // Add cross streets every 20 units
        for (let i = -80; i <= 80; i += 20) {
            if (i === 0) continue; // Skip center

            // Horizontal side roads
            const sideRoadH = new THREE.Mesh(
                new THREE.BoxGeometry(sideRoadLength, 0.1, sideRoadWidth),
                roadMaterial
            );
            sideRoadH.position.set(i, 0.01, 0);
            sideRoadH.receiveShadow = true;
            scene.add(sideRoadH);
            roads.push(sideRoadH);

            // Vertical side roads
            const sideRoadV = new THREE.Mesh(
                new THREE.BoxGeometry(sideRoadWidth, 0.1, sideRoadLength),
                roadMaterial
            );
            sideRoadV.position.set(0, 0.01, i);
            sideRoadV.receiveShadow = true;
            scene.add(sideRoadV);
            roads.push(sideRoadV);
        }

        // Road markings
        const roadMarkingMaterial = new THREE.MeshStandardMaterial({ color: 0xffffff });

        // Add center lines
        const centerLineGeometry = new THREE.BoxGeometry(mainRoadLength, 0.11, 0.2);
        const centerLine = new THREE.Mesh(centerLineGeometry, roadMarkingMaterial);
        centerLine.position.set(0, 0.02, 0);
        scene.add(centerLine);

        const centerLineVGeometry = new THREE.BoxGeometry(0.2, 0.11, mainRoadLength);
        const centerLineV = new THREE.Mesh(centerLineVGeometry, roadMarkingMaterial);
        centerLineV.position.set(0, 0.02, 0);
        scene.add(centerLineV);

        // Add crosswalk markings
        const crosswalkGeometry = new THREE.BoxGeometry(4, 0.11, 0.5);
        for (let i = -2; i <= 2; i += 1) {
            const crosswalkH = new THREE.Mesh(crosswalkGeometry, roadMarkingMaterial);
            crosswalkH.position.set(i * 2, 0.02, 0);
            scene.add(crosswalkH);

            const crosswalkV = new THREE.Mesh(
                new THREE.BoxGeometry(0.5, 0.11, 4),
                roadMarkingMaterial
            );
            crosswalkV.position.set(0, 0.02, i * 2);
            scene.add(crosswalkV);
        }

        // Buildings
        const buildings = [];
        let currentBuildingType = 'small';

        // Building materials
        const buildingMaterials = {
            wall: new THREE.MeshStandardMaterial({ color: 0xcccccc, roughness: 0.7 }),
            window: new THREE.MeshStandardMaterial({ color: 0x87CEEB, roughness: 0.1, metalness: 0.9 }),
            roof: new THREE.MeshStandardMaterial({ color: 0x8B4513, roughness: 0.8 })
        };

        // Create a preview building
        let previewBuilding = createBuilding(currentBuildingType);
        previewBuilding.visible = false;
        scene.add(previewBuilding);

        // Function to create different types of buildings
        function createBuilding(type) {
            const building = new THREE.Group();

            switch(type) {
                case 'small':
                    // Small office building
                    const smallBase = new THREE.Mesh(
                        new THREE.BoxGeometry(4, 4, 4),
                        buildingMaterials.wall
                    );
                    smallBase.castShadow = true;
                    smallBase.receiveShadow = true;
                    building.add(smallBase);

                    // Windows
                    for (let i = 0; i < 4; i++) {
                        const window = new THREE.Mesh(
                            new THREE.BoxGeometry(0.8, 0.8, 0.1),
                            buildingMaterials.window
                        );
                        window.position.set(-1.5 + (i % 2) * 3, 1.5 - Math.floor(i / 2) * 2, 2.01);
                        building.add(window);
                    }

                    // Roof
                    const smallRoof = new THREE.Mesh(
                        new THREE.BoxGeometry(4.5, 0.5, 4.5),
                        buildingMaterials.roof
                    );
                    smallRoof.position.y = 4.25;
                    building.add(smallRoof);
                    break;

                case 'medium':
                    // Medium apartment building
                    const mediumBase = new THREE.Mesh(
                        new THREE.BoxGeometry(6, 8, 6),
                        buildingMaterials.wall
                    );
                    mediumBase.castShadow = true;
                    mediumBase.receiveShadow = true;
                    building.add(mediumBase);

                    // Windows
                    for (let i = 0; i < 6; i++) {
                        for (let j = 0; j < 3; j++) {
                            const window = new THREE.Mesh(
                                new THREE.BoxGeometry(1, 1, 0.1),
                                buildingMaterials.window
                            );
                            window.position.set(-2.5 + (i % 2) * 5, 3 - j * 3, 3.01);
                            building.add(window);
                        }
                    }

                    // Roof
                    const mediumRoof = new THREE.Mesh(
                        new THREE.BoxGeometry(6.5, 0.5, 6.5),
                        buildingMaterials.roof
                    );
                    mediumRoof.position.y = 8.25;
                    building.add(mediumRoof);
                    break;

                case 'large':
                    // Large commercial building
                    const largeBase = new THREE.Mesh(
                        new THREE.BoxGeometry(10, 6, 10),
                        buildingMaterials.wall
                    );
                    largeBase.castShadow = true;
                    largeBase.receiveShadow = true;
                    building.add(largeBase);

                    // Windows
                    for (let i = 0; i < 5; i++) {
                        for (let j = 0; j < 3; j++) {
                            for (let k = 0; k < 2; k++) {
                                const window = new THREE.Mesh(
                                    new THREE.BoxGeometry(1.5, 1.5, 0.1),
                                    buildingMaterials.window
                                );
                                window.position.set(
                                    -radek4 + i * 2,
                                    2.5 - j * 2,
                                    k === 0 ? 5.01 : -5.01
                                );
                                building.add(window);
                            }
                        }
                    }

                    // Roof
                    const largeRoof = new THREE.Mesh(
                        new THREE.ConeGeometry(7, 2, 4),
                        buildingMaterials.roof
                    );
                    largeRoof.position.y = 6;
                    largeRoof.rotation.y = Math.PI / 4;
                    building.add(largeRoof);
                    break;

                case 'skyscraper':
                    // Skyscraper
                    const skyscraperBase = new THREE.Mesh(
                        new THREE.BoxGeometry(5, 20, 5),
                        buildingMaterials.wall
                    );
                    skyscraperBase.castShadow = true;
                    skyscraperBase.receiveShadow = true;
                    building.add(skyscraperBase);

                    // Windows
                    for (let i = 0; i < 4; i++) {
                        for (let j = 0; j < 10; j++) {
                            const window = new THREE.Mesh(
                                new THREE.BoxGeometry(0.8, 1.5, 0.1),
                                buildingMaterials.window
                            );
                            window.position.set(
                                -2 + (i % 2) * 4,
                                9 - j * 1.8,
                                2.51
                            );
                            building.add(window);
                        }
                    }

                    // Roof
                    const skyscraperRoof = new THREE.Mesh(
                        new THREE.ConeGeometry(3, 3, 4),
                        buildingMaterials.roof
                    );
                    skyscraperRoof.position.y = 20 + 1.5;
                    skyscraperRoof.rotation.y = Math.PI / 4;
                    building.add(skyscraperRoof);
                    break;

                case 'house':
                    // Residential house
                    const houseBase = new THREE.Mesh(
                        new THREE.BoxGeometry(5, 3, 5),
                        buildingMaterials.wall
                    );
                    houseBase.castShadow = true;
                    houseBase.receiveShadow = true;
                    building.add(houseBase);

                    // Door
                    const door = new THREE.Mesh(
                        new THREE.BoxGeometry(1.5, 2, 0.2),
                        new THREE.MeshStandardMaterial({ color: 0x8B4513 })
                    );
                    door.position.set(0, -0.5, 2.51);
                    building.add(door);

                    // Windows
                    for (let i = 0; i < 2; i++) {
                        for (let j = 0; j < 2; j++) {
                            const window = new THREE.Mesh(
                                new THREE.BoxGeometry(1, 1, 0.1),
                                buildingMaterials.window
                            );
                            window.position.set(
                                -2 + i * 4,
                                1,
                                j === 0 ? 2.51 : -2.51
                            );
                            building.add(window);
                        }
                    }

                    // Roof
                    const roofShape = new THREE.Shape();
                    roofShape.moveTo(-3, 0);
                    roofShape.lineTo(0, 3);
                    roofShape.lineTo(3, 0);

                    const roofGeometry = new THREE.ExtrudeGeometry(roofShape, {
                        depth: 5.2,
                        bevelEnabled: false
                    });

                    const houseRoof = new THREE.Mesh(
                        roofGeometry,
                        buildingMaterials.roof
                    );
                    houseRoof.position.y = 3;
                    houseRoof.rotation.y = Math.PI / 2;
                    building.add(houseRoof);
                    break;
            }

            return building;
        }

        // Place a building
        function placeBuilding(position, type) {
            const building = createBuilding(type);
            building.position.copy(position);
            scene.add(building);
            buildings.push(building);
            document.getElementById('building-count').textContent = buildings.length;
        }

        // Vehicles
        const vehicles = [];
        const vehicleMaterial = new THREE.MeshStandardMaterial({ color: 0xff0000 });

        function createCar() {
            const car = new THREE.Group();

            // Car body
            const body = new THREE.Mesh(
                new THREE.BoxGeometry(2, 1, 4),
                vehicleMaterial
            );
            body.castShadow = true;
            body.receiveShadow = true;
            car.add(body);

            // Wheels
            const wheelGeometry = new THREE.CylinderGeometry(0.5, 0.5, 0.4, 16);
            const wheelMaterial = new THREE.MeshStandardMaterial({ color: 0x333333 });

            for (let i = 0; i < 4; i++) {
                const wheel = new THREE.Mesh(wheelGeometry, wheelMaterial);
                wheel.castShadow = true;
                wheel.receiveShadow = true;

                if (i < 2) {
                    wheel.position.set(-0.8, -0.5, 1.5 - i * 3);
                } else {
                    wheel.position.set(0.8, -0.5, 1.5 - (i - 2) * 3);
                }

                wheel.rotation.z = Math.PI / 2;
                car.add(wheel);
            }

            // Windows
            const window = new THREE.Mesh(
                new THREE.BoxGeometry(1.8, 0.8, 1.5),
                buildingMaterials.window
            );
            window.position.set(0, 0.5, -0.5);
            car.add(window);

            return car;
        }

        // Add some initial traffic
        function addTraffic() {
            const carCount = 10;

            for (let i = 0; i < carCount; i++) {
                const car = createCar();
                let road;
                let lane = Math.random() > 0.5 ? 1 : -1;

                // Choose a random road
                if (Math.random() > 0.5) {
                    // Horizontal road
                    road = roads[0];
                    car.position.x = Math.random() * 180 - 90;
                    car.position.z = lane * (mainRoadWidth / 2 - 0.5);
                } else {
                    // Vertical road
                    road = roads[1];
                    car.position.z = Math.random() * 180 - 90;
                    car.position.x = lane * (mainRoadWidth / 2 - 0.5);
                    car.rotation.y = Math.PI / 2;
                }

                car.position.y = 0.5;
                car.userData = {
                    speed: 0.05 + Math.random() * 0.05,
                    direction: Math.random() > 0.5 ? 1 : -1,
                    road: roads.indexOf(road)
                };

                if (road === roads[1]) {
                    car.userData.direction *= -1; // Reverse direction for vertical roads
                }

                scene.add(car);
                vehicles.push(car);
            }
        }

        // Update traffic movement
        function updateTraffic() {
            for (const car of vehicles) {
                const road = roads[car.userData.road];
                const isHorizontal = road === roads[0];

                if (isHorizontal) {
                    car.position.x += car.userData.speed * car.userData.direction;

                    // Teleport car to other side if it goes off the road
                    if ((car.userData.direction > 0 && car.position.x > 100) || 
                        (car.userData.direction < 0 && car.position.x < -100)) {
                        car.position.x = car.userData.direction > 0 ? -100 : 100;
                    }
                } else {
                    car.position.z += car.userData.speed * car.userData.direction;

                    // Teleport car to other side if it goes off the road
                    if ((car.userData.direction > 0 && car.position.z > 100) || 
                        (car.userData.direction < 0 && car.position.z < -100)) {
                        car.position.z = car.userData.direction > 0 ? -100 : 100;
                    }
                }
            }
        }

        // Add initial traffic
        addTraffic();

        // Player vehicle
        let playerVehicle = null;
