I'll create a single-page HTML file with Three.js that lets you place buildings, drive through the town, and includes traffic. This will be a complete self-contained solution.

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>3D Town Builder</title>
    <style>
        body { 
            margin: 0; 
            overflow: hidden; 
            font-family: Arial, sans-serif;
        }
        #info {
            position: absolute;
            top: 10px;
            left: 10px;
            background: rgba(0,0,0,0.7);
            color: white;
            padding: 10px;
            border-radius: 5px;
            z-index: 100;
            pointer-events: none;
        }
        #controls {
            position: absolute;
            bottom: 10px;
            left: 10px;
            background: rgba(0,0,0,0.7);
            color: white;
            padding: 10px;
            border-radius: 5px;
            z-index: 100;
            pointer-events: all;
        }
        button {
            margin: 5px;
            padding: 8px 12px;
            cursor: pointer;
            background: #4CAF50;
            color: white;
            border: none;
            border-radius: 4px;
        }
        button:hover {
            background: #45a049;
        }
        .control-group {
            margin-bottom: 10px;
        }
        .control-group label {
            display: block;
            margin-bottom: 5px;
        }
        #roadWidth {
            width: 60px;
        }
        #buildingType {
            width: 100px;
        }
        #buildingSize {
            width: 60px;
        }
        #speedControl {
            width: 100px;
        }
    </style>
</head>
<body>
    <div id="info">3D Town Builder<br>Click to place buildings. WASD to drive. Mouse to look.</div>
    <div id="controls">
        <h3>Town Builder Controls</h3>

        <div class="control-group">
            <label for="buildingType">Building Type:</label>
            <select id="buildingType">
                <option value="house">House</option>
                <option value="apartment">Apartment</option>
                <option value="store">Store</option>
                <option value="factory">Factory</option>
                <option value="church">Church</option>
                <option value="skyscraper">Skyscraper</option>
            </select>
        </div>

        <div class="control-group">
            <label for="buildingSize">Size:</label>
            <select id="buildingSize">
                <option value="small">Small</option>
                <option value="medium">Medium</option>
                <option value="large">Large</option>
            </select>
        </div>

        <div class="control-group">
            <label for="roadWidth">Road Width:</label>
            <select id="roadWidth">
                <option value="10">Narrow (10)</option>
                <option value="15" selected>Standard (15)</option>
                <option value="20">Wide (20)</option>
            </select>
        </div>

        <div class="control-group">
            <label for="speedControl">Traffic Speed:</label>
            <select id="speedControl">
                <option value="0.5">Slow (0.5x)</option>
                <option value="1.0" selected>Normal (1.0x)</option>
                <option value="1.5">Fast (1.5x)</option>
            </select>
        </div>

        <button id="placeRoad">Place Road</button>
        <button id="clearAll">Clear All</button>
        <button id="toggleTraffic">Toggle Traffic</button>
    </div>

    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/build/three.min.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/examples/js/controls/OrbitControls.js"></script>
    <script>
        // Main application
        let scene, camera, renderer, controls;
        let player;
        let buildings = [];
        let roads = [];
        let traffic = [];
        let roadWidth = 15;
        let trafficSpeed = 1.0;
        let trafficEnabled = true;
        let currentBuildingType = 'house';
        let currentBuildingSize = 'medium';
        let isPlacingRoad = false;
        let grid = {};
        let gridSize = 50;
        let cellSize = 5;

        // Initialize the scene
        init();
        animate();

        function init() {
            // Scene setup
            scene = new THREE.Scene();
            scene.background = new THREE.Color(0x87CEEB); // Sky blue

            // Camera setup
            camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
            camera.position.set(0, 10, 20);

            // Renderer
            renderer = new THREE.WebGLRenderer({ antialias: true });
            renderer.setSize(window.innerWidth, window.innerHeight);
            renderer.shadowMap.enabled = true;
            renderer.shadowMap.type = THREE.PCFSoftShadowMap;
            document.body.appendChild(renderer.domElement);

            // Controls
            controls = new THREE.OrbitControls(camera, renderer.domElement);
            controls.enableDamping = true;
            controls.dampingFactor = 0.05;
            controls.minDistance = 5;
            controls.maxDistance = 50;

            // Lights
            const ambientLight = new THREE.AmbientLight(0x404040, 1);
            scene.add(ambientLight);

            const directionalLight = new THREE.DirectionalLight(0xffffff, 0.8);
            directionalLight.position.set(10, 20, 10);
            directionalLight.castShadow = true;
            directionalLight.shadow.mapSize.width = 2048;
            directionalLight.shadow.mapSize.height = 2048;
            directionalLight.shadow.camera.near = 0.5;
            directionalLight.shadow.camera.far = 50;
            directionalLight.shadow.camera.left = -25;
            directionalLight.shadow.camera.right = 25;
            directionalLight.shadow.camera.top = 25;
            directionalLight.shadow.camera.bottom = -25;
            scene.add(directionalLight);

            // Ground
            const groundGeometry = new THREE.PlaneGeometry(100, 100);
            const groundMaterial = new THREE.MeshStandardMaterial({ 
                color: 0x555555,
                roughness: 0.8,
                metalness: 0.2
            });
            const ground = new THREE.Mesh(groundGeometry, groundMaterial);
            ground.rotation.x = -Math.PI / 2;
            ground.receiveShadow = true;
            scene.add(ground);

            // Create the grid for road placement
            createRoadGrid();

            // Create player (first-person controller)
            createPlayer();

            // Create initial buildings
            createInitialBuildings();

            // Create initial roads
            createInitialRoads();

            // Event listeners
            window.addEventListener('resize', onWindowResize);
            renderer.domElement.addEventListener('click', onClick);

            // Control button events
            document.getElementById('buildingType').addEventListener('change', function(e) {
                currentBuildingType = e.target.value;
            });

            document.getElementById('buildingSize').addEventListener('change', function(e) {
                currentBuildingSize = e.target.value;
            });

            document.getElementById('roadWidth').addEventListener('change', function(e) {
                roadWidth = parseFloat(e.target.value);
            });

            document.getElementById('speedControl').addEventListener('change', function(e) {
                trafficSpeed = parseFloat(e.target.value);
            });

            document.getElementById('placeRoad').addEventListener('click', function() {
                isPlacingRoad = !isPlacingRoad;
                this.textContent = isPlacingRoad ? 'Cancel Road Placement' : 'Place Road';
                document.getElementById('info').innerHTML = isPlacingRoad ? 
                    'Click to place road segments. Click to end road.' : 
                    'Click to place buildings. WASD to drive. Mouse to look.';
            });

            document.getElementById('clearAll').addEventListener('click', function() {
                clearAll();
            });

            document.getElementById('toggleTraffic').addEventListener('click', function() {
                trafficEnabled = !trafficEnabled;
                this.textContent = trafficEnabled ? 'Disable Traffic' : 'Enable Traffic';
            });

            // Keyboard controls
            window.addEventListener('keydown', onKeyDown);
            window.addEventListener('keyup', onKeyUp);

            // Mouse controls
            document.addEventListener('mousemove', onMouseMove);
            mouse = { x: 0, y: 0 };
        }

        // Mouse position for raycasting
        let mouse = { x: 0, y: 0 };

        function onMouseMove(event) {
            mouse.x = (event.clientX / window.innerWidth) * 2 - 1;
            mouse.y = -(event.clientY / window.innerHeight) * 2 + 1;
        }

        function onClick(event) {
            // Raycaster for object picking
            const raycaster = new THREE.Raycaster();
            raycaster.setFromCamera(mouse, camera);

            // Check for intersections with the ground
            const intersects = raycaster.intersectObjects([ground]);

            if (intersects.length > 0) {
                const point = intersects[0].point;
                const x = Math.round(point.x / cellSize) * cellSize;
                const z = Math.round(point.z / cellSize) * cellSize;

                if (isPlacingRoad) {
                    placeRoadAt(x, z);
                } else {
                    placeBuildingAt(x, z);
                }
            }
        }

        function placeBuildingAt(x, z) {
            const buildingType = currentBuildingType;
            const size = currentBuildingSize;

            // Check if there's already a building or road here
            const key = `${x},${z}`;
            if (grid[key]) {
                return; // Can't place on existing road or building
            }

            let sizeScale;
            switch(size) {
                case 'small': sizeScale = 0.7; break;
                case 'medium': sizeScale = 1.0; break;
                case 'large': sizeScale = 1.5; break;
                default: sizeScale = 1.0;
            }

            let building;
            const height = 5 * sizeScale;
            const width = 4 * sizeScale;
            const depth = 4 * sizeScale;

            switch(buildingType) {
                case 'house':
                    building = createHouse(x, z, width, height, depth);
                    break;
                case 'apartment':
                    building = createApartment(x, z, width, height, depth);
                    break;
                case 'store':
                    building = createStore(x, z, width, height, depth);
                    break;
                case 'factory':
                    building = createFactory(x, z, width, height, depth);
                    break;
                case 'church':
                    building = createChurch(x, z, width, height, depth);
                    break;
                case 'skyscraper':
                    building = createSkyscraper(x, z, width, height, depth);
                    break;
            }

            if (building) {
                scene.add(building);
                buildings.push({
                    mesh: building,
                    x: x,
                    z: z,
                    type: buildingType,
                    size: size
                });
                grid[key] = 'building';
            }
        }

        function placeRoadAt(x, z) {
            const key = `${x},${z}`;

            // Check if there's already a building here
            if (grid[key] === 'building') {
                return; // Can't place road on building
            }

            // Create road segment
            const roadGeometry = new THREE.PlaneGeometry(roadWidth, cellSize);
            const roadMaterial = new THREE.MeshStandardMaterial({ 
                color: 0x222222,
                roughness: 0.9,
                metalness: 0.1
            });
            const road = new THREE.Mesh(roadGeometry, roadMaterial);
            road.rotation.x = -Math.PI / 2;
            road.position.set(x, 0.01, z);
            road.receiveShadow = true;
            scene.add(road);

            // Add lane markings
            const laneGeometry = new THREE.PlaneGeometry(0.2, cellSize);
            const laneMaterial = new THREE.MeshStandardMaterial({ color: 0xFFFFFF });
            const lane1 = new THREE.Mesh(laneGeometry, laneMaterial);
            const lane2 = new THREE.Mesh(laneGeometry, laneMaterial);
            lane1.rotation.x = -Math.PI / 2;
            lane2.rotation.x = -Math.PI / 2;
            lane1.position.set(x, 0.02, z);
            lane2.position.set(x, 0.02, z);
            lane1.position.x -= roadWidth/4;
            lane2.position.x += roadWidth/4;
            scene.add(lane1);
            scene.add(lane2);

            roads.push({
                mesh: road,
                lane1: lane1,
                lane2: lane2,
                x: x,
                z: z,
                width: roadWidth
            });

            grid[key] = 'road';

            // Check for adjacent road segments and connect them visually
            const adjacentPositions = [
                {x: x + cellSize, z: z},
                {x: x - cellSize, z: z},
                {x: x, z: z + cellSize},
                {x: x, z: z - cellSize}
            ];

            for (const pos of adjacentPositions) {
                const adjKey = `${pos.x},${pos.z}`;
                if (grid[adjKey] === 'road') {
                    // Find the road segment
                    const adjacentRoad = roads.find(r => r.x === pos.x && r.z === pos.z);
                    if (adjacentRoad) {
                        // We'll handle connections in the render loop for simplicity
                    }
                }
            }
        }

