        function createSkyscraper(x, z, width, height, depth) {
            const group = new THREE.Group();

            // Main tower
            const towerGeometry = new THREE.BoxGeometry(width, height * 2, depth);
            const towerMaterial = new THREE.MeshStandardMaterial({ color: 0x4F4F4F });
            const tower = new THREE.Mesh(towerGeometry, towerMaterial);
            tower.position.set(x, height, z);
            tower.castShadow = true;
            tower.receiveShadow = true;
            group.add(tower);

            // Roof
            const roofGeometry = new THREE.BoxGeometry(width * 0.8, height * 0.3, depth * 0.8);
            const roofMaterial = new THREE.MeshStandardMaterial({ color: 0x333333 });
            const roof = new THREE.Mesh(roofGeometry, roofMaterial);
            roof.position.set(x, height + height * 2 + height * 0.15, z);
