            group.add(roof);

            // Windows
            const windowGeometry = new THREE.BoxGeometry(0.4, 0.4, 0.05);
            const windowMaterial = new THREE.MeshStandardMaterial({ color: 0xE0F7FF });

            const numRows = 10;
            const numCols = 6;
            const windowSpacingX = width / (numCols + 1);
            const windowSpacingZ = depth / (numRows + 1);

            // Front side
            for (let i = 0; i < numCols; i++) {
                for (let j = 0; j < numRows; j++) {
                    if (j % 2 === 0) {
                        const window = new THREE.Mesh(windowGeometry, windowMaterial);
                        window.position.set(
                            x - width/2 + windowSpacingX * (i + 1), 
                            height/2 + height * 0.4 + windowSpacingZ * (j + 1), 
                            z + depth/2 - 0.1
                        );
                        window.castShadow = true;
                        group.add(window);
                    }
                }
            }

            // Left side
            for (let i = 0; i < numCols; i++) {
                for (let j = 0; j < numRows; j++) {
                    if (j % 2 === 0) {
                        const window = new THREE.Mesh(windowGeometry, windowMaterial);
                        window.position.set(
                            x - width/2 + windowSpacingX * (i + 1), 
                            height/2 + height * 0.4 + windowSpacingZ * (j + 1), 
                            z - depth/2 + 0.1
                        );
                        window.castShadow = true;
                        group.add(window);
                    }
                }
            }

            // Right side
            for (let i = 0; i < numCols; i++) {
                for (let j = 0; j < numRows; j++) {
                    if (j % 2 === 0) {
                        const window = new THREE.Mesh(windowGeometry, windowMaterial);
                        window.position.set(
                            x + width/2 - windowSpacingX * (i + 1), 
                            height/2 + height * 0.4 + windowSpacingZ * (j + 1), 
                            z + depth/2 - 0.1
                        );
                        window.castShadow = true;
                        group.add(window);
                    }
                }
            }

            // Back side
            for (let i = 0; i < numCols; i++) {
                for (let j = 0; j < numRows; j++) {
                    if (j % 2 === 0) {
                        const window = new THREE.Mesh(windowGeometry, windowMaterial);
                        window.position.set(
                            x - width/2 + windowSpacingX * (i + 1), 
                            height/2 + height * 0.4 + windowSpacingZ * (j + 1), 
                            z - depth/2 + 0.1
                        );
                        window.castShadow = true;
                        group.add(window);
                    }
                }
            }

            // Antenna
            const antennaGeometry = new THREE.CylinderGeometry(0.1, 0.05, 2, 8);
            const antennaMaterial = new THREE.MeshStandardMaterial({ color: 0xCCCCCC });
            const antenna = new THREE.Mesh(antennaGeometry, antennaMaterial);
            antenna.position.set(x, height + height * 2 + 1, z);
            antenna.castShadow = true;
            group.add(antenna);

            return group;
        }

