        function createRoadGrid() {
            // Create a grid for placing roads
            for (let x = -gridSize; x <= gridSize; x += cellSize) {
                for (let z = -gridSize; z <= gridSize; z += cellSize) {
                    const key = `${x},${z}`;
                    grid[key] = null;
                }
            }
        }

        function createTraffic() {
            // Create traffic vehicles
            const trafficCount = 8;

            for (let i = 0; i < trafficCount; i++) {
                const roadSegment = roads[Math.floor(Math.random() * roads.length)];
                if (!roadSegment) continue;

                // Create a car
                const carGeometry = new THREE.BoxGeometry(0.8, 0.5, 1.5);
                const carMaterial = new THREE.MeshStandardMaterial({ 
                    color: Math.random() * 0xffffff
                });
                const car = new THREE.Mesh(carGeometry, carMaterial);

                // Position the car on the road
                car.position.set(roadSegment.x, 0.25, roadSegment.z);

                // Get a random direction based on road segment
                let direction;
                const roadIndex = roads.indexOf(roadSegment);
                const nextRoadIndex = (roadIndex + 1) % roads.length;
                const nextRoad = roads[nextRoadIndex];

                if (nextRoad) {
                    // Calculate direction vector
                    const dx = nextRoad.x - roadSegment.x;
                    const dz = nextRoad.z - roadSegment.z;
                    direction = new THREE.Vector3(dx, 0, dz).normalize();
                } else {
                    // Default direction
                    direction = new THREE.Vector3(1, 0, 0);
                }

                // Rotate car to face direction
                const angle = Math.atan2(direction.z, direction.x);
                car.rotation.y = angle;

                // Add to scene
                scene.add(car);

                // Store traffic data
                traffic.push({
                    mesh: car,
                    position: new THREE.Vector3(roadSegment.x, 0.25, roadSegment.z),
                    direction: direction,
                    speed: 0.05 * trafficSpeed,
                    roadIndex: roadIndex
                });
            }
        }

        function updateTraffic() {
            if (!trafficEnabled) return;

            traffic.forEach(car => {
                // Move car along its direction
                car.position.x += car.direction.x * car.speed;
                car.position.z += car.direction.z * car.speed;

                // Update car rotation to face direction
                const angle = Math.atan2(car.direction.z, car.direction.x);
                car.mesh.rotation.y = angle;

                // Check if car has reached the end of a road segment
                // This is a simplified approach - in a real game, you'd use pathfinding
                const road = roads.find(r => 
                    Math.abs(r.x - car.position.x) < 1 && 
                    Math.abs(r.z - car.position.z) < 1
                );

                if (road) {
                    const roadIndex = roads.indexOf(road);

                    // Check for next road segment in the network
                    const adjacentRoads = roads.filter(r => 
                        (Math.abs(r.x - road.x) < cellSize * 1.5 && Math.abs(r.z - road.z) < cellSize * 1.5) &&
                        (!(Math.abs(r.x - road.x) < 0.5 && Math.abs(r.z - road.z) < 0.5)) // Not same road
                    );

                    if (adjacentRoads.length > 0) {
                        // Simple pathfinding: pick a random adjacent road
                        const nextRoad = adjacentRoads[Math.floor(Math.random() * adjacentRoads.length)];
                        const dx = nextRoad.x - car.position.x;
                        const dz = nextRoad.z - car.position.z;
                        car.direction.set(dx, 0, dz).normalize();
                    }
                }

                // Check if car is out of bounds and needs to be repositioned
                if (Math.abs(car.position.x) > gridSize + 5 || Math.abs(car.position.z) > gridSize + 5) {
                    // Reposition car to a random road segment
                    const randomRoad = roads[Math.floor(Math.random() * roads.length)];
                    if (randomRoad) {
                        car.position.set(randomRoad.x, 0.25, randomRoad.z);
                        const nextRoad = roads[(roads.indexOf(randomRoad) + 1) % roads.length];
                        if (nextRoad) {
                            const dx = nextRoad.x - randomRoad.x;
                            const dz = nextRoad.z - randomRoad.z;
                            car.direction.set(dx, 0, dz).normalize();
                        }
                    }
                }
            });
        }

