function isBuilding(r, c){ return inBounds(r,c) && grid[r][c] && grid[r][c].type === 'building'; }

/* ---- Window texture generator ---- */
function makeWindowTex(base, win, cols, rows){
  const cv = document.createElement('canvas');
  cv.width = 128; cv.height = 128;
  const ctx = cv.getContext('2d');
  ctx.fillStyle = base; ctx.fillRect(0,0,128,128);
  const padX = 8, padY = 8;
  const cw = (128 - padX*2) / cols;
  const ch = (128 - padY*2) / rows;
  for(let r=0; r<rows; r++){
    for(let c=0; c<cols; c++){
      // randomly lit windows
      const lit = Math.random() > 0.35;
      ctx.fillStyle = lit ? win : '#000000';
      const x = padX + c*cw + cw*0.18;
      const y = padY + r*ch + ch*0.18;
      ctx.fillRect(x, y, cw*0.64, ch*0.64);
    }
  }
  const tex = new THREE.CanvasTexture(cv);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.magFilter = THREE.NearestFilter;
  return tex;
}

