/* ============================================================
   PLACEMENT
============================================================ */
function placeAt(r, c, tool){
  if(!inBounds(r,c)) return;
  if(grid[r][c]){
    // occupied - bulldoze first if bulldoze tool
    if(tool === 'bulldoze'){
      removeAt(r, c);
      return;
    }
    return;
  }
  if(tool === 'bulldoze') return;

  if(tool === 'road'){
    const m = createRoadMesh();
    cellToWorld(r, c, m.position);
    m.position.y = 0;
    scene.add(m);
    grid[r][c] = { type:'road', mesh:m };
  } else if(tool !== 'bulldoze'){
    const m = createBuilding(tool);
    cellToWorld(r, c, m.position);
    scene.add(m);
    grid[r][c] = { type:'building', kind:tool, mesh:m };
  }
  updateStats();
}

function removeAt(r, c){
  const item = grid[r][c];
  if(!item) return;
  scene.remove(item.mesh);
  item.mesh.traverse(o=>{
    if(o.isMesh){
      o.geometry.dispose();
      const m = o.material;
      if(Array.isArray(m)) m.forEach(mm=>{ if(mm.map) mm.map.dispose(); mm.dispose(); });
      else { if(m.map) m.map.dispose(); m.dispose(); }
    }
  });
  grid[r][c] = null;
  // remove traffic cars on this cell
  for(let i=trafficCars.length-1; i>=0; i--){
    if(trafficCars[i].cell.r === r && trafficCars[i].cell.c === c){
      scene.remove(trafficCars[i].mesh);
      trafficCars.splice(i, 1);
    }
  }
  updateStats();
}

