/* ============================================================
   PLAYER CAR
============================================================ */
const player = {
  car: createCarMesh(0xff4422),
  speed: 0,
  angle: 0,
  pos: new THREE.Vector3(),
  active: false,
};
player.car.visible = false;
scene.add(player.car);

function enterDriveMode(){
  const roads = getRoadCells();
  if(roads.length === 0){
    toast('Build some roads first!');
    return false;
  }
  // find road closest to center
  let best = roads[0], bestD = Infinity;
  for(const r of roads){
    const w = cellToWorld(r.r, r.c);
    const d = w.length();
    if(d < bestD){ bestD = d; best = r; }
  }
  cellToWorld(best.r, best.c, player.pos);
  player.angle = 0;
  player.speed = 0;
  player.car.visible = true;
  player.active = true;
  orbit.enabled = false;
  return true;
}

function exitDriveMode(){
  player.active = false;
  player.car.visible = false;
  player.speed = 0;
  orbit.enabled = true;
}

function updatePlayer(dt){
  if(!player.active) return;
  const accel = 18;
  const maxFwd = 22;
  const maxRev = 10;
  const turnRate = 1.8;

  if(keys.w) player.speed += accel * dt;
  else if(keys.s) player.speed -= accel * dt;
  else player.speed *= (1 - 0.6 * dt);

  if(keys.space) player.speed *= (1 - 3 * dt);

  player.speed = Math.max(-maxRev, Math.min(maxFwd, player.speed));

  const steer = (keys.a ? 1 : 0) - (keys.d ? 1 : 0);
  const speedFactor = Math.min(1, Math.abs(player.speed) / 6);
  player.angle += steer * turnRate * dt * speedFactor * Math.sign(player.speed || 1);

  const next = new THREE.Vector3(
    player.pos.x + Math.sin(player.angle) * player.speed * dt,
    0,
    player.pos.z + Math.cos(player.angle) * player.speed * dt
  );

  // bounds
  const lim = HALF - 1;
  if(Math.abs(next.x) > lim || Math.abs(next.z) > lim){
    player.speed *= -0.2;
  } else {
    const cell = worldToCell(next.x, next.z);
    if(isBuilding(cell.r, cell.c)){
      player.speed *= -0.25;
    } else {
      player.pos.copy(next);
    }
  }

  player.car.position.copy(player.pos);
  player.car.position.y = 0;
  player.car.rotation.y = player.angle;

  // camera follow
  const camTarget = new THREE.Vector3(
    player.pos.x - Math.sin(player.angle) * 9,
    5,
    player.pos.z - Math.cos(player.angle) * 9
  );
  camera.position.lerp(camTarget, 0.12);
  const lookAt = new THREE.Vector3(
    player.pos.x + Math.sin(player.angle) * 4,
    1.5,
    player.pos.z + Math.cos(player.angle) * 4
  );
  camera.lookAt(lookAt);
}

/* ============================================================
   TRAFFIC AI
============================================================ */
const DIRS = [
  { dr:-1, dc:0 },  // 0: N
  { dr:0,  dc:1 },  // 1: E
  { dr:1,  dc:0 },  // 2: S
  { dr:0,  dc:-1 }, // 3: W
];
function dirAngle(d){
  // car forward is +z (south) at angle 0
  return [Math.PI, Math.PI/2, 0, -Math.PI/2][d];
}

function getRoadCells(){
  const out = [];
  for(let r=0; r<GRID; r++)
    for(let c=0; c<GRID; c++)
      if(isRoad(r,c)) out.push({r,c});
  return out;
}

function spawnTrafficCar(){
  const roads = getRoadCells();
  if(roads.length === 0) return false;
  // try to find a cell with at least one road neighbor
  let attempts = 0;
  while(attempts++ < 20){
    const cell = roads[Math.floor(Math.random()*roads.length)];
    const valid = [];
    DIRS.forEach((d,i)=>{
      if(isRoad(cell.r + d.dr, cell.c + d.dc)) valid.push(i);
    });
    if(valid.length === 0) continue;
    const dir = valid[Math.floor(Math.random()*valid.length)];
    const mesh = createCarMesh(randomCarColor());
    scene.add(mesh);
    trafficCars.push({
      mesh, cell, dir,
      progress: Math.random() * 0.5,
      speed: 3 + Math.random() * 4,
    });
    return true;
  }
  return false;
}

function removeTrafficCar(){
  if(trafficCars.length === 0) return;
  const t = trafficCars.pop();
  scene.remove(t.mesh);
  t.mesh.traverse(o=>{ if(o.isMesh) o.geometry.dispose(); });
}

function updateTraffic(dt){
  for(const t of trafficCars){
    t.progress += t.speed * dt / CELL;
    let safety = 0;
    while(t.progress >= 1 && safety++ < 4){
      t.progress -= 1;
      const d = DIRS[t.dir];
      const nr = t.cell.r + d.dr, nc = t.cell.c + d.dc;
      if(!isRoad(nr, nc)){
        // road gone - try to find any road neighbor from current cell, else stay
        const opts = [];
        DIRS.forEach((dd,i)=>{
          if(isRoad(t.cell.r + dd.dr, t.cell.c + dd.dc)) opts.push(i);
        });
        if(opts.length === 0){ t.progress = 0; break; }
        t.dir = opts[Math.floor(Math.random()*opts.length)];
        t.progress = 0;
        break;
      }
      t.cell = { r:nr, c:nc };
      // pick next direction (avoid reverse)
      const opp = (t.dir + 2) % 4;
      const opts = [];
      DIRS.forEach((dd,i)=>{
        if(i === opp) return;
        if(isRoad(t.cell.r + dd.dr, t.cell.c + dd.dc)) opts.push(i);
      });
      if(opts.length === 0){
        // dead end - reverse
        t.dir = opp;
      } else {
        t.dir = opts[Math.floor(Math.random()*opts.length)];
      }
    }
    // position
    const d = DIRS[t.dir];
    const w0 = cellToWorld(t.cell.r, t.cell.c);
    const w1 = cellToWorld(t.cell.r + d.dr, t.cell.c + d.dc);
    const pos = w0.clone().lerp(w1, t.progress);
    // offset to right side
    const right = new THREE.Vector3(-d.dr, 0, d.dc).multiplyScalar(0.7);
    pos.add(right);
    t.mesh.position.copy(pos);
    t.mesh.position.y = 0;
    t.mesh.rotation.y = dirAngle(t.dir);
  }
}

function maintainTraffic(){
  while(trafficCars.length < targetTraffic){
    if(!spawnTrafficCar()) break;
  }
  while(trafficCars.length > targetTraffic){
    removeTrafficCar();
  }
}

