function buildStarterCity(){
  // road loop
  const r1 = 12, r2 = 28;
  for(let c = r1; c <= r2; c++){
    placeAt(r1, c, 'road');
    placeAt(r2, c, 'road');
  }
  for(let r = r1; r <= r2; r++){
    placeAt(r, r1, 'road');
    placeAt(r, r2, 'road');
  }
  // crossroad
  for(let c = r1; c <= r2; c++) placeAt(20, c, 'road');
  for(let r = r1; r <= r2; r++) placeAt(r, 20, 'road');

  // buildings inside
  placeAt(15, 15, 'house');
  placeAt(15, 16, 'house');
  placeAt(15, 17, 'shop');
  placeAt(16, 15, 'office');
  placeAt(17, 15, 'shop');
