/* ---- Pointer / placement ---- */
const raycaster = new THREE.Raycaster();
const mouse = new THREE.Vector2();
const groundPlane = new THREE.Plane(new THREE.Vector3(0,1,0), 0);

function updateHover(e){
  mouse.x = (e.clientX / innerWidth) * 2 - 1;
  mouse.y = -(e.clientY / innerHeight) * 2 + 1;
  raycaster.setFromCamera(mouse, camera);
  const hit = new THREE.Vector3();
  if(raycaster.ray.intersectPlane(groundPlane, hit)){
    const cell = worldToCell(hit.x, hit.z);
    if(inBounds(cell.r, cell.c)){
      hoverCell = cell;
      if(mode === 'build'){
        cellToWorld(cell.r, cell.c, ghost.position);
        ghost.position.y = 0.08;
        ghost.visible = true;
        const occ = grid[cell.r][cell.c] !== null;
        const isBull = currentTool === 'bulldoze';
        ghost.material.color.setHex(
          (occ && isBull) ? 0xff7a59 :
          occ ? 0xff3030 :
          currentTool === 'bulldoze' ? 0x666666 :
          0x7aff8a
        );
      } else {
        ghost.visible = false;
      }
    } else {
      hoverCell = null;
      ghost.visible = false;
    }
  }
}

let mouseDown = null;
canvas.addEventListener('mousemove', updateHover);
canvas.addEventListener('mousedown', e=>{ mouseDown = {x:e.clientX, y:e.clientY}; });
canvas.addEventListener('mouseup', e=>{
  if(!mouseDown) return;
  const dx = e.clientX - mouseDown.x, dy = e.clientY - mouseDown.y;
  mouseDown = null;
  if(dx*dx + dy*dy > 25) return; // was a drag
  if(mode !== 'build') return;
  updateHover(e);
  if(hoverCell) placeAt(hoverCell.r, hoverCell.c, currentTool);
});

window.addEventListener('keydown', e=>{
  const k = e.key.toLowerCase();
  keys[k] = true;
  if(k === ' '){ keys.space = true; e.preventDefault(); }
});
window.addEventListener('keyup', e=>{
  const k = e.key.toLowerCase();
  keys[k] = false;
  if(k === ' ') keys.space = false;
});

window.addEventListener('resize', ()=>{
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});

/* ---- Toast ---- */
function toast(msg, dur=2200){
  const t = document.getElementById('toast');
  t.textContent = msg;
  t.classList.add('show');
  clearTimeout(t._tm);
  t._tm = setTimeout(()=>t.classList.remove('show'), dur);
}

