<link rel="icon" href="data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'><text y='.9em' font-size='90'>🏗️</text></svg>">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Bungee&family=Sora:wght@400;600;700;800&display=swap" rel="stylesheet">
<style>
:root{ --ink:#171a24; --paper:#f6f1e3; --yellow:#ffcf3f; --teal:#2fbf9f; --red:#ff5a5a; }
*{box-sizing:border-box; margin:0; padding:0}
html,body{height:100%; overflow:hidden}
body{font-family:'Sora',system-ui,sans-serif; background:#0d1017; color:var(--ink)}
#c{position:fixed; inset:0; display:block}
.hidden{display:none !important}
kbd{font-family:'Bungee'; font-size:9px; background:var(--ink); color:var(--paper); padding:3px 6px; border-radius:6px; letter-spacing:.4px; white-space:nowrap}
#top{position:fixed; top:0; left:0; right:0; display:flex; align-items:flex-start; justify-content:space-between; padding:14px 16px; pointer-events:none; z-index:10; gap:10px}
#brand{display:flex; flex-direction:column; gap:7px}
#brand h1{font-family:'Bungee'; font-size:21px; letter-spacing:1px; color:var(--paper); text-shadow:2.5px 2.5px 0 var(--yellow)}
.chip{align-self:flex-start; font-family:'Bungee'; font-size:10px; padding:4px 9px; border:2.5px solid var(--ink); border-radius:8px; transform:rotate(-2deg); box-shadow:3px 3px 0 rgba(23,26,36,.8); color:var(--ink)}
.chip.build{background:var(--yellow)} .chip.drive{background:var(--teal)}
#right{display:flex; gap:8px; align-items:center; pointer-events:auto; flex-wrap:wrap; justify-content:flex-end}
.stat{font-size:11px; font-weight:700; color:var(--paper); background:rgba(23,26,36,.82); border:2px solid rgba(246,241,227,.28); border-radius:9px; padding:5px 9px}
.stat b{font-family:'Bungee'; font-size:11px; color:var(--yellow)}
button{font-family:'Bungee'; font-size:10px; letter-spacing:.5px; color:var(--ink); background:var(--paper); border:3px solid var(--ink); border-radius:10px; padding:8px 10px; cursor:pointer; box-shadow:3px 3px 0 var(--ink); transition:transform .12s, box-shadow .12s, background .12s}
button:hover{background:var(--yellow); transform:translate(-1px,-1px); box-shadow:4px 4px 0 var(--ink)}
button:active{transform:translate(2px,2px); box-shadow:1px 1px 0 var(--ink)}
button.off{opacity:.55}
#palette{position:fixed; bottom:14px; left:50%; transform:translateX(-50%); display:flex; gap:8px; flex-wrap:wrap; justify-content:center; max-width:96vw; z-index:10; pointer-events:none}
.card{pointer-events:auto; width:66px; display:flex; flex-direction:column; align-items:center; gap:3px; padding:8px 4px 7px; background:var(--paper); border:3px solid var(--ink); border-radius:13px; box-shadow:4px 4px 0 rgba(23,26,36,.85); cursor:pointer; position:relative; transition:transform .15s, box-shadow .15s, background .15s; color:var(--ink)}
.card:hover{transform:translateY(-6px) rotate(-1.5deg); box-shadow:6px 9px 0 rgba(23,26,36,.85); background:#fffdf6}
.card.sel{background:var(--yellow); transform:translateY(-6px); box-shadow:6px 9px 0 rgba(23,26,36,.85)}
.card.dem.sel{background:var(--red); color:#fff}
.card svg{width:30px; height:30px; stroke:currentColor; fill:none; stroke-width:2; stroke-linecap:round; stroke-linejoin:round}
.card .nm{font-size:8.5px; font-weight:800; text-transform:uppercase; letter-spacing:.4px}
.card .sz{font-size:8px; font-weight:700; background:var(--ink); color:var(--paper); border-radius:6px; padding:1px 6px}
.card .key{position:absolute; top:-8px; left:-8px; font-family:'Bungee'; font-size:9px; background:var(--ink); color:var(--yellow); border:2px solid var(--paper); border-radius:7px; padding:2px 5px}
.card.dem .key{color:#fff}
#hint{position:fixed; bottom:114px; left:50%; transform:translateX(-50%); background:rgba(23,26,36,.88); color:var(--paper); font-size:11px; font-weight:600; padding:8px 14px; border-radius:999px; border:2px solid rgba(246,241,227,.22); z-index:9; white-space:nowrap; pointer-events:none}
#hint kbd{background:rgba(246,241,227,.15); color:var(--yellow); border-radius:4px; padding:1px 5px}
#toast{position:fixed; top:64px; left:50%; transform:translateX(-50%) translateY(-8px); font-family:'Bungee'; font-size:12px; background:var(--yellow); border:3px solid var(--ink); border-radius:11px; padding:9px 15px; box-shadow:4px 4px 0 rgba(23,26,36,.85); opacity:0; transition:opacity .25s, transform .25s; z-index:15; pointer-events:none}
#toast.show{opacity:1; transform:translateX(-50%) translateY(0)}
#speedo{position:fixed; right:16px; bottom:16px; background:rgba(23,26,36,.9); color:var(--paper); border:3px solid var(--paper); border-radius:14px; padding:10px 16px 12px; text-align:right; z-index:10; box-shadow:5px 5px 0 rgba(23,26,36,.5)}
#spd{font-family:'Bungee'; font-size:42px; color:var(--yellow); line-height:1}
#speedo small{font-size:10px; font-weight:700; letter-spacing:1px; margin-left:4px; color:rgba(246,241,227,.7)}
#spdBar{width:140px; height:8px; background:rgba(246,241,227,.18); border-radius:4px; margin-top:8px; overflow:hidden}
#spdBar i{display:block; height:100%; width:0%; background:var(--teal); border-radius:4px; transition:width .1s linear}
.ov{position:fixed; inset:0; display:flex; align-items:center; justify-content:center; background:rgba(10,12,20,.66); z-index:30; pointer-events:auto; padding:18px}
.panel{background:var(--paper); border:4px solid var(--ink); border-radius:18px; box-shadow:12px 12px 0 rgba(10,12,20,.5); padding:26px 30px; max-width:640px; width:100%; max-height:calc(100vh - 40px); overflow:auto; position:relative; transform:rotate(-.5deg)}
.eyebrow{font-size:10px; font-weight:800; letter-spacing:3px; text-transform:uppercase; color:rgba(23,26,36,.55); margin-bottom:8px}
.title{font-family:'Bungee'; font-size:clamp(38px,7vw,58px); line-height:.95; text-shadow:4px 4px 0 var(--yellow), 8px 8px 0 rgba(23,26,36,.15); margin-bottom:10px}
.tag{font-size:13.5px; font-weight:600; max-width:48ch; margin-bottom:16px}
.cols{display:grid; grid-template-columns:1fr 1fr; gap:10px 22px; margin-bottom:18px}
.cols h3{font-family:'Bungee'; font-size:12px; background:var(--ink); color:var(--paper); display:inline-block; padding:4px 9px; border-radius:8px; margin-bottom:8px}
.cols ul{list-style:none}
.cols li{font-size:12px; font-weight:600; margin:7px 0; display:flex; align-items:center; gap:8px; flex-wrap:wrap}
.bigbtn{font-size:15px; background:var(--yellow); border-radius:14px; padding:14px 24px; box-shadow:5px 5px 0 var(--ink)}
.foot{margin-top:14px; font-size:10.5px; font-weight:600; color:rgba(23,26,36,.5)}
.stamp{position:absolute; top:16px; right:16px; font-family:'Bungee'; font-size:9px; color:var(--red); border:3px solid var(--red); border-radius:9px; padding:7px 9px; transform:rotate(7deg); opacity:.8; text-align:center; line-height:1.5}
@media (max-width:720px){ .cols{grid-template-columns:1fr} .card{width:58px} #hint{white-space:normal; max-width:92vw; text-align:center} }
</style>
</head>
<body>
<canvas id="c"></canvas>

<div id="top">
  <div id="brand">
    <h1>BLOCKVILLE</h1>
    <span id="modeChip" class="chip build">BUILD MODE</span>
  </div>
  <div id="right">
    <span class="stat">🏠 <b id="stB">0</b></span>
    <span class="stat">🚗 <b id="stC">0</b></span>
    <span class="stat"><b id="stF">60</b> FPS</span>
    <button id="bMode">DRIVE [V]</button>
    <button id="bNight">NIGHT [N]</button>
    <button id="bSound">SOUND [M]</button>
    <button id="bHelp">HELP [H]</button>
  </div>
</div>

<div id="palette"></div>
<div id="hint"></div>
<div id="toast"></div>
<div id="speedo" class="hidden"><span id="spd">0</span><small>KM/H</small><div id="spdBar"><i></i></div></div>

<div id="help" class="ov hidden">
  <div class="panel" style="max-width:560px">
    <div class="eyebrow">Field manual</div>
    <h2 style="font-family:'Bungee'; font-size:24px; margin-bottom:12px">CONTROLS</h2>
    <div class="cols">
      <div class="col"><h3>BUILD MODE</h3><ul>
        <li><kbd>1–0</kbd> pick a structure</li>
        <li><kbd>CLICK</kbd> / hold+drag to place</li>
        <li><kbd>R</kbd> rotate</li>
        <li><kbd>RMB</kbd> or <kbd>X</kbd> demolish</li>
        <li><kbd>A / D</kbd> orbit &nbsp; <kbd>WHEEL</kbd> zoom</li>
        <li><kbd>ESC</kbd> deselect</li>
      </ul></div>
      <div class="col"><h3>DRIVE MODE</h3><ul>
        <li><kbd>V</kbd> switch mode</li>
        <li><kbd>W A S D</kbd> / arrows to drive</li>
        <li><kbd>SPACE</kbd> handbrake</li>
        <li><kbd>N</kbd> day / night</li>
        <li><kbd>M</kbd> sound</li>
        <li>grass is slow — buildings hurt</li>
      </ul></div>
    </div>
    <button class="bigbtn" id="helpClose">GOT IT [H]</button>
  </div>
</div>

<div id="start" class="ov">
  <div class="panel">
    <div class="stamp">PERMIT #042<br>APPROVED</div>
    <div class="eyebrow">Town Planning Dept. · Form 042</div>
    <h1 class="title">BLOCK<br>VILLE</h1>
    <p class="tag">Raise cottages, shops and towers on a live grid — then hop in the car and cruise your own town. The traffic's already running.</p>
    <div class="cols">
      <div class="col">
        <h3>BUILD</h3>
        <ul>
          <li><kbd>1–0</kbd> pick a structure</li>
          <li><kbd>CLICK</kbd> place · drag to paint</li>
          <li><kbd>R</kbd> rotate · <kbd>RMB</kbd> demolish</li>
          <li><kbd>A / D</kbd> orbit · <kbd>WHEEL</kbd> zoom</li>
        </ul>
      </div>
      <div class="col">
        <h3>DRIVE</h3>
        <ul>
          <li><kbd>V</kbd> hop in the car</li>
          <li><kbd>W A S D</kbd> / arrows to drive</li>
          <li><kbd>SPACE</kbd> handbrake</li>
          <li><kbd>N</kbd> day &amp; night · <kbd>M</kbd> sound</li>
        </ul>
      </div>
    </div>
    <button id="startBtn" class="bigbtn">START BUILDING ▸</button>
    <p class="foot">runs entirely in your browser · three.js · no installs</p>
  </div>
</div>

<div id="err" class="ov hidden">
  <div class="panel" style="max-width:420px; text-align:center">
    <h2 style="font-family:'Bungee'; font-size:26px; margin-bottom:10px">OFFLINE?</h2>
    <p style="font-size:13px; font-weight:600">Couldn't load three.js from the CDN. Check your connection and reload the page.</p>
  </div>
</div>

<script type="module">
let THREE;
try { THREE = await import('https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js'); }
catch(e){ document.getElementById('err').classList.remove('hidden'); throw e; }

/* ============================== helpers / dom ============================== */
const $ = s => document.querySelector(s);
const canvas = $('#c');
const paletteEl=$('#palette'), hintEl=$('#hint'), toastEl=$('#toast'),
      modeChip=$('#modeChip'), speedEl=$('#speedo'), spdVal=$('#spd'),
      spdBar=$('#spdBar i'), stB=$('#stB'), stC=$('#stC'), stF=$('#stF'),
      bMode=$('#bMode'), bNight=$('#bNight'), bSound=$('#bSound'),
      bHelp=$('#bHelp'), helpEl=$('#help'), startEl=$('#start');

const rand=(a,b)=>a+Math.random()*(b-a);
const pick=a=>a[(Math.random()*a.length)|0];

/* ============================== constants ============================== */
const TILE=10, TMIN=-21, TMAX=20, WORLD=420;
const LINES=[-150,-90,-30,30,90,150];   // road centerlines (each road is 2 tiles wide)
const LANEOFF=5;

/* ============================== renderer / scene ============================== */
const renderer=new THREE.WebGLRenderer({canvas, antialias:true});
renderer.setPixelRatio(Math.min(devicePixelRatio,2));
renderer.setSize(innerWidth,innerHeight);
renderer.shadowMap.enabled=true;
renderer.shadowMap.type=THREE.PCFSoftShadowMap;
renderer.outputColorSpace=THREE.SRGBColorSpace;
renderer.toneMapping=THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure=1.05;

const scene=new THREE.Scene();
scene.fog=new THREE.Fog(0xcfe8f5, 260, 1100);
const camera=new THREE.PerspectiveCamera(50, innerWidth/innerHeight, .5, 3200);
camera.position.set(240,210,260);

const tmpV=new THREE.Vector3(), tmpV2=new THREE.Vector3(), tmpC=new THREE.Color();
const nightMats=[], blinkers=[];

/* sky dome */
const skyU={ top:{value:new THREE.Color(0x4f9be8)}, bot:{value:new THREE.Color(0xcfe8f5)} };
scene.add(new THREE.Mesh(new THREE.SphereGeometry(1700,24,16), new THREE.ShaderMaterial({
  uniforms:skyU, side:THREE.BackSide, depthWrite:false, fog:false,
  vertexShader:`varying vec3 vP; void main(){ vP=position; gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0); }`,
  fragmentShader:`varying vec3 vP; uniform vec3 top,bot; void main(){ float h=normalize(vP).y; vec3 c=mix(bot,top,smoothstep(-0.05,0.5,h)); gl_FragColor=vec4(c,1.0); }`
})));

/* stars */
const starGeo=new THREE.BufferGeometry();
{ const sp=new Float32Array(600*3); let n=0;
  while(n<600){ const v=new THREE.Vector3().randomDirection();
    if(v.y>0.12){ sp[n*3]=v.x*1600; sp[n*3+1]=v.y*1600; sp[n*3+2]=v.z*1600; n++; } }
  starGeo.setAttribute('position', new THREE.BufferAttribute(sp,3)); }
const starMat=new THREE.PointsMaterial({color:0xdfe8ff, size:1.6, sizeAttenuation:false, transparent:true, opacity:0, fog:false});
scene.add(new THREE.Points(starGeo, starMat));

/* sun & moon discs */
function discSprite(hex, rgba){
  const cv=document.createElement('canvas'); cv.width=cv.height=128;
  const g=cv.getContext('2d');
  const gr=g.createRadialGradient(64,64,6,64,64,64);
  gr.addColorStop(0,rgba); gr.addColorStop(.5,rgba); gr.addColorStop(1,'rgba(255,255,255,0)');
  g.fillStyle=gr; g.fillRect(0,0,128,128);
  const t=new THREE.CanvasTexture(cv); t.colorSpace=THREE.SRGBColorSpace;
  const s=new THREE.Sprite(new THREE.SpriteMaterial({map:t, transparent:true, fog:false, depthWrite:false}));
  return s;
}
const sun=discSprite('#fff3b0','rgba(255,243,176,1)');  sun.position.set(620,430,-520);  sun.scale.setScalar(120); scene.add(sun);
const moon=discSprite('#dfe8ff','rgba(223,232,255,1)'); moon.position.set(-560,380,430); moon.scale.setScalar(72);  scene.add(moon);

/* lights */
const hemi=new THREE.HemisphereLight(0xbfd9ff, 0x6a8f4f, 1); scene.add(hemi);
const sunLight=new THREE.DirectionalLight(0xfff2dd, 1.7);
sunLight.castShadow=true;
sunLight.shadow.mapSize.set(2048,2048);
Object.assign(sunLight.shadow.camera, {left:-95,right:95,top:95,bottom:-95,near:20,far:520});
sunLight.shadow.bias=-0.0004; sunLight.shadow.normalBias=.6;
scene.add(sunLight, sunLight.target);
const sunOff=new THREE.Vector3(120,170,70);

/* ============================== textures ============================== */
function noiseTex(base, spots, spotC, size=512){
  const cv=document.createElement('canvas'); cv.width=cv.height=size;
  const g=cv.getContext('2d');
  g.fillStyle=base; g.fillRect(0,0,size,size);
  g.fillStyle=spotC;
  for(let i=0;i<spots;i++){
    g.globalAlpha=rand(.04,.12);
    g.beginPath();
    g.ellipse(Math.random()*size, Math.random()*size, rand(4,26), rand(4,20), Math.random()*3, 0, 7);
    g.fill();
  }
  g.globalAlpha=1;
  const t=new THREE.CanvasTexture(cv);
  t.wrapS=t.wrapT=THREE.RepeatWrapping; t.colorSpace=THREE.SRGBColorSpace;
  return t;
}
function facadeTex(cols, rows, base, win, lit, litC='#ffd27a'){
  const S=256;
  const cv=document.createElement('canvas'); cv.width=cv.height=S;
  const g=cv.getContext('2d');
  g.fillStyle=base; g.fillRect(0,0,S,S);
  g.fillStyle='rgba(0,0,0,.08)'; g.fillRect(0,S-14,S,14);
  const ec=document.createElement('canvas'); ec.width=ec.height=S;
  const e=ec.getContext('2d'); e.fillStyle='#000'; e.fillRect(0,0,S,S);
  const cw=S/cols, ch=S/rows;
  for(let r=0;r<rows;r++) for(let c=0;c<cols;c++){
    const ww=cw*.52, wh=ch*.52, x=c*cw+(cw-ww)/2, y=r*ch+(ch-wh)/2;
    g.fillStyle=win; g.fillRect(x,y,ww,wh);
    g.strokeStyle='rgba(0,0,0,.35)'; g.lineWidth=3; g.strokeRect(x,y,ww,wh);
    if(Math.random()<lit){ e.fillStyle=litC; e.fillRect(x,y,ww,wh); }
  }
  const map=new THREE.CanvasTexture(cv); map.colorSpace=THREE.SRGBColorSpace;
  const em=new THREE.CanvasTexture(ec);
  return {map, em};
}
function facadeMat(cols, rows, base, win, lit, litC, k=1.1){
  const {map, em}=facadeTex(cols, rows, base, win, lit, litC);
  const m=new THREE.MeshStandardMaterial({map, emissive:0xffffff, emissiveMap:em, emissiveIntensity:0, roughness:.85});
  nightMats.push({m, k});
  return m;
}
function signMat(text, bg, fg, glowK=0){
  const cv=document.createElement('canvas'); cv.width=512; cv.height=128;
  const g=cv.getContext('2d');
  g.fillStyle=bg; g.fillRect(0,0,512,128);
  g.font='900 66px "Arial Black", Arial, sans-serif';
  g.textAlign='center'; g.textBaseline='middle';
  if(glowK){ g.shadowColor=fg; g.shadowBlur=26; }
  g.fillStyle=fg; g.fillText(text,256,68);
  const map=new THREE.CanvasTexture(cv); map.colorSpace=THREE.SRGBColorSpace;
  const m=new THREE.MeshStandardMaterial({map, roughness:.7, emissive:0xffffff, emissiveMap:glowK?map:undefined, emissiveIntensity:0});
  if(glowK) nightMats.push({m, k:glowK});
  return m;
}
function stripeTex(c1, c2, n=8){
  const cv=document.createElement('canvas'); cv.width=256; cv.height=64;
  const g=cv.getContext('2d');
  for(let i=0;i<n;i++){ g.fillStyle=i%2?c1:c2; g.fillRect(i*256/n,0,256/n,64); }
  const t=new THREE.CanvasTexture(cv); t.colorSpace=THREE.SRGBColorSpace; return t;
}

/* ============================== geometry helpers ============================== */
const geoC=new Map();
function boxGeo(w,h,d){ const k=`b${w}|${h}|${d}`; let g=geoC.get(k); if(!g){g=new THREE.BoxGeometry(w,h,d); geoC.set(k,g);} return g; }
function cylGeo(a,b,h,s=12){ const k=`c${a}|${b}|${h}|${s}`; let g=geoC.get(k); if(!g){g=new THREE.CylinderGeometry(a,b,h,s); geoC.set(k,g);} return g; }
function B(g, mat, x=0,y=0,z=0, rx=0,ry=0,rz=0){
  const m=new THREE.Mesh(g,mat); m.position.set(x,y,z); m.rotation.set(rx,ry,rz);
  m.castShadow=true; m.receiveShadow=true; return m;
}
function gableGeo(ridgeLen, span, rise, ov=.55){
  const key=`g${ridgeLen}|${span}|${rise}`;
  let g=geoC.get(key);
  if(!g){
    const s=new THREE.Shape();
    s.moveTo(-span/2,0); s.lineTo(span/2,0); s.lineTo(0,rise); s.closePath();
    g=new THREE.ExtrudeGeometry(s,{depth:ridgeLen, bevelEnabled:false});
    g.translate(0,0,-ridgeLen/2);
    geoC.set(key,g);
  }
  return g;
}
function gable(geo, mat, x,y,z, ry=0){
  const m=new THREE.Mesh(geo,mat); m.position.set(x,y,z); m.rotation.y=ry; m.castShadow=true; return m;
}
const roofCache=new Map();
function roofMat(c){ let m=roofCache.get(c); if(!m){m=new THREE.MeshStandardMaterial({color:c, roughness:.9}); roofCache.set(c,m);} return m; }

/* ============================== world: ground, roads, markings, lamps ============================== */
const occ=new Map();          // "tx,tz" -> {kind:'road'|'b'|'t'|'l', id?}
const placed=new Map();       // pid -> {type, tiles[], group}
let pidCounter=1;

const grassTex=noiseTex('#6fae4e', 110, '#4c7a35'); grassTex.repeat.set(10,10);
const groundMat=new THREE.MeshStandardMaterial({map:grassTex, roughness:1});
const ground=new THREE.Mesh(new THREE.PlaneGeometry(WORLD,WORLD), groundMat);
ground.rotation.x=-Math.PI/2; ground.receiveShadow=true; scene.add(ground);
const skirtMat=new THREE.MeshStandardMaterial({color:0x5d9445, roughness:1});
const skirt=new THREE.Mesh(new THREE.PlaneGeometry(4200,4200), skirtMat);
skirt.rotation.x=-Math.PI/2; skirt.position.y=-.12; scene.add(skirt);

const grid=new THREE.GridHelper(WORLD, 42, 0xffffff, 0xffffff);
grid.material.transparent=true; grid.material.opacity=.16; grid.position.y=.06; scene.add(grid);

/* mark road tiles */
for(const c of LINES){
  const t0=Math.floor((c-10)/TILE), t1=Math.floor((c+9.999)/TILE);
  for(let t=t0;t<=t1;t++) for(let s=TMIN;s<=TMAX;s++){
    occ.set(t+','+s,{kind:'road'}); occ.set(s+','+t,{kind:'road'});
  }
}

/* road + sidewalk strips */
const asphaltTex=noiseTex('#3a3f47', 160, '#2c3038', 256);
const asphaltMats=[];
function roadMat(rx,ry){
  const t=asphaltTex.clone(); t.needsUpdate=true; t.repeat.set(rx,ry);
  const m=new THREE.MeshStandardMaterial({map:t, roughness:.95});
  asphaltMats.push(m); return m;
}
const sidewalkMat=new THREE.MeshStandardMaterial({color:0xa7adb5, roughness:1});
for(const c of LINES){
  const v=new THREE.Mesh(new THREE.PlaneGeometry(20,WORLD), roadMat(2,24));
