/* ============================== placement ============================== */
function canPlace(fw,fd,tx,tz){
  for(let i=0;i<fw;i++) for(let j=0;j<fd;j++){
    const x=tx+i, z=tz+j;
    if(x<TMIN||x>TMAX||z<TMIN||z>TMAX) return false;
    if(occ.has(x+','+z)) return false;
  }
  const cx=(tx+fw/2)*TILE, cz=(tz+fd/2)*TILE;
  if(Math.abs(P.pos.x-cx)<(fw*TILE+8)/2 && Math.abs(P.pos.z-cz)<(fd*TILE+8)/2) return false;
  return true;
}
function place(type, tx, tz, rot, silent=false){
  const def=CATALOG_BY_ID[type];
  const [fw,fd]=rot%2?[def.d,def.w]:[def.w,def.d];
  if(!canPlace(fw,fd,tx,tz)) return false;
  const g=FACTORY[type]();
  g.rotation.y=rot*Math.PI/2;
  const cx=(tx+fw/2)*TILE, cz=(tz+fd/2)*TILE;
  g.position.set(cx,0,cz);
  const pid=pidCounter++;
  g.userData.pid=pid;
  scene.add(g);
  const kind=type==='tree'?'t':type==='lamp'?'l':'b';
  const tiles=[];
  for(let i=0;i<fw;i++) for(let j=0;j<fd;j++){ const k=(tx+i)+','+(tz+j); occ.set(k,{kind,id:pid}); tiles.push(k); }
  placed.set(pid,{type, tiles, group:g});
  if(!silent) puff(cx,cz, kind==='b');
  updateStats();
  return true;
}
function demolish(pid, silent=false){
  const p=placed.get(pid); if(!p) return;
  placed.delete(pid);
  p.tiles.forEach(k=>occ.delete(k));
  scene.remove(p.group);
  if(!silent){ puff(p.group.position.x, p.group.position.z, true); sfx.boom(); }
  updateStats();
}

