/* ============================== audio ============================== */
let mode='build', started=false, placing=false;
const sfx=(()=>{
  let ctx=null, master=null, engOsc, engOsc2, engGain, engFilter, noiseBuf=null, muted=false;
  function init(){
    if(ctx) return;
    ctx=new (window.AudioContext||window.webkitAudioContext)();
    master=ctx.createGain(); master.gain.value=muted?0:.5; master.connect(ctx.destination);
    const len=(ctx.sampleRate*.4)|0;
    noiseBuf=ctx.createBuffer(1,len,ctx.sampleRate);
    const d=noiseBuf.getChannelData(0); for(let i=0;i<len;i++) d[i]=Math.random()*2-1;
    engGain=ctx.createGain(); engGain.gain.value=0;
    engFilter=ctx.createBiquadFilter(); engFilter.type='lowpass'; engFilter.frequency.value=500;
    engOsc=ctx.createOscillator(); engOsc.type='sawtooth'; engOsc.frequency.value=50;
    engOsc2=ctx.createOscillator(); engOsc2.type='square'; engOsc2.frequency.value=25;
    const g2=ctx.createGain(); g2.gain.value=.4;
    engOsc.connect(engFilter); engOsc2.connect(g2); g2.connect(engFilter);
    engFilter.connect(engGain); engGain.connect(master);
    engOsc.start(); engOsc2.start();
  }
  function beep(f,d,type='triangle',v=.3,slide){
    if(!ctx||muted) return;
    const o=ctx.createOscillator(), g=ctx.createGain();
    o.type=type; o.frequency.value=f;
    const t=ctx.currentTime;
    if(slide) o.frequency.exponentialRampToValueAtTime(slide, t+d);
    g.gain.setValueAtTime(v,t); g.gain.exponentialRampToValueAtTime(.001,t+d);
    o.connect(g); g.connect(master); o.start(t); o.stop(t+d+.02);
  }
  function noise(d,v,f=1200){
    if(!ctx||muted) return;
    const s=ctx.createBufferSource(); s.buffer=noiseBuf;
    const fl=ctx.createBiquadFilter(); fl.type='bandpass'; fl.frequency.value=f; fl.Q.value=.8;
    const g=ctx.createGain(); const t=ctx.currentTime;
    g.gain.setValueAtTime(v,t); g.gain.exponentialRampToValueAtTime(.001,t+d);
    s.connect(fl); fl.connect(g); g.connect(master); s.start(t); s.stop(t+d);
  }
  return {
    init,
    engine(v, throttle){
      if(!ctx) return;
      const t=ctx.currentTime, f=45+Math.abs(v)*2.6+throttle*14;
      engOsc.frequency.setTargetAtTime(f,t,.06);
      engOsc2.frequency.setTargetAtTime(f/2,t,.06);
      engFilter.frequency.setTargetAtTime(300+Math.abs(v)*22,t,.1);
      engGain.gain.setTargetAtTime((mode==='drive' && !muted) ? .035+Math.abs(v)/34*.05+throttle*.02 : 0, t, .08);
    },
    place(){ beep(340,.09,'triangle',.35); setTimeout(()=>beep(560,.12,'triangle',.28), 60); },
    boom(){ noise(.3,.5,700); beep(120,.25,'sawtooth',.35,55); },
    err(){ beep(150,.12,'square',.2,110); },
    tick(){ beep(700,.05,'square',.12); },
    whoosh(){ noise(.35,.3,1400); },
    setMute(m){ muted=m; if(master) master.gain.value=m?0:.5; }
  };
})();

/* ============================== traffic graph ============================== */
const nodes=[], outE={};
function addNode(x,z){ const n={x,z,id:nodes.length}; nodes.push(n); return n; }
const nodeAt={};
LINES.forEach((x,i)=>LINES.forEach((z,j)=>{ nodeAt[i+','+j]=addNode(x,z); }));
const bN={}, bS={}, bW={}, bE={};
LINES.forEach((x,i)=>{ bN[i]=addNode(x,-205); bS[i]=addNode(x,205); });
LINES.forEach((z,j)=>{ bW[j]=addNode(-205,z); bE[j]=addNode(205,z); });
const dirEdges=[];
function link(a,b){
  const dx=b.x-a.x, dz=b.z-a.z, len=Math.hypot(dx,dz), ex=dx/len, ez=dz/len;
  const e1={a,b,dirx:ex,dirz:ez,len,rx:-ez,rz:ex,rev:null};
  const e2={a:b,b:a,dirx:-ex,dirz:-ez,len,rx:ez,rz:-ex,rev:null};
  e1.rev=e2; e2.rev=e1;
  dirEdges.push(e1,e2);
  (outE[a.id]=outE[a.id]||[]).push(e1);
  (outE[b.id]=outE[b.id]||[]).push(e2);
}
for(let i=0;i<6;i++) for(let j=0;j<6;j++){
  if(i<5) link(nodeAt[i+','+j], nodeAt[(i+1)+','+j]);
  if(j<5) link(nodeAt[i+','+j], nodeAt[i+','+(j+1)]);
}
LINES.forEach((x,i)=>{ link(bN[i], nodeAt[i+',0']); link(bS[i], nodeAt[i+',5']); });
LINES.forEach((z,j)=>{ link(bW[j], nodeAt['0,'+j]); link(bE[j], nodeAt['5,'+j]); });

function edgePoint(e,t,v){
  const off=LANEOFF*Math.min(1, Math.min(t,1-t)*e.len/9);
  v.set(e.a.x+e.dirx*e.len*t+e.rx*off, 0, e.a.z+e.dirz*e.len*t+e.rz*off);
  return v;
}
function pickNext(e){
  const out=outE[e.b.id]||[];
  const cands=out.filter(x=>x!==e.rev);
  if(!cands.length) return e.rev;
  const ws=cands.map(c=>(c.dirx*e.dirx+c.dirz*e.dirz)>.9?5:1);
  let total=0; ws.forEach(w=>total+=w);
  let r=Math.random()*total;
  for(let i=0;i<cands.length;i++){ r-=ws[i]; if(r<=0) return cands[i]; }
  return cands[cands.length-1];
}

const CAR_COLORS=['#d94f3d','#3d7dd9','#e8b04b','#4fae82','#e5e1d5','#8a6f9e','#c9c9c9','#d97b2f','#5b7f9e','#b85c4a'];
function makeCarMesh(color, van){
  const g=new THREE.Group();
  const cm=new THREE.MeshStandardMaterial({color, roughness:.5, metalness:.15});
  const L=van?7.4:6.6, bodyH=van?2.3:1.05;
  g.add(B(boxGeo(3.3,bodyH,L), cm, 0,.75+bodyH/2,0));
  if(!van) g.add(B(boxGeo(2.9,.95,3.1), new THREE.MeshStandardMaterial({color:0x22303e, roughness:.3, metalness:.2}), 0,2.05,-.35));
  for(const sx of [-1,1]) for(const sz of [-1,1])
    g.add(B(cylGeo(.62,.62,.42,10), wheelMat, sx*1.55,.62,sz*(L/2-1.5), 0,0,Math.PI/2));
  const hlM=new THREE.MeshStandardMaterial({color:0xfff6d8, emissive:0xfff2b0, emissiveIntensity:0, roughness:.4});
  nightMats.push({m:hlM, k:2.2});
  const tlM=new THREE.MeshStandardMaterial({color:0x7a1d16, emissive:0xff2b1a, emissiveIntensity:0, roughness:.4});
  nightMats.push({m:tlM, k:1.4});
  g.add(B(boxGeo(.55,.35,.12), hlM, -1.05,1.15,L/2+.02));
  g.add(B(boxGeo(.55,.35,.12), hlM, 1.05,1.15,L/2+.02));
  g.add(B(boxGeo(.55,.35,.12), tlM, -1.05,1.15,-L/2-.02));
  g.add(B(boxGeo(.55,.35,.12), tlM, 1.05,1.15,-L/2-.02));
  return g;
}
const traffic=[];
function spawnTraffic(n){
  let tries=0;
  while(traffic.length<n && tries<800){
    tries++;
    const e=dirEdges[(Math.random()*dirEdges.length)|0];
    const t=Math.random()*.85;
    const p=edgePoint(e,t,tmpV);
    let ok=true;
    if(p.distanceToSquared(P.pos)<169) ok=false;
    for(const o of traffic){ if(tmpV.distanceToSquared(o.group.position)<169){ ok=false; break; } }
    if(!ok) continue;
    const car={edge:e, t, speed:6, cruise:13+Math.random()*6, h:Math.atan2(e.dirx,e.dirz),
               group:makeCarMesh(pick(CAR_COLORS), Math.random()<.3), _obst:1e9};
    car.group.position.copy(p); car.group.rotation.y=car.h;
    scene.add(car.group); traffic.push(car);
  }
}
function updateTraffic(dt){
  for(const a of traffic) a._obst=1e9;
  for(const a of traffic){
    for(const b of traffic){
      if(a===b) continue;
      let d=-1;
      if(b.edge===a.edge && b.t>a.t) d=(b.t-a.t)*a.edge.len;
      else if(b.edge.a===a.edge.b) d=(1-a.t)*a.edge.len + b.t*b.edge.len;
      if(d>0 && d<a._obst && d<34) a._obst=d;
    }
    const dx=P.pos.x-a.group.position.x, dz=P.pos.z-a.group.position.z;
    const ahead=dx*a.edge.dirx+dz*a.edge.dirz;
    const lat=Math.abs(dx*a.edge.rx+dz*a.edge.rz);
    if(ahead>0 && lat<5.5 && ahead<34) a._obst=Math.min(a._obst, ahead-3);
  }
  for(const a of traffic){
    let target=a.cruise;
    if(a._obst<24) target=Math.min(target, Math.max(0,(a._obst-3.5)*1.2));
    if(a._obst<1.5) target=0;
    if(target<a.speed) a.speed=Math.max(target, a.speed-24*dt);
    else a.speed=Math.min(target, a.speed+7*dt);
    a.t+=a.speed*dt/a.edge.len;
    while(a.t>=1){ a.t-=1; a.edge=pickNext(a.edge); }
    edgePoint(a.edge, a.t, a.group.position);
    const th=Math.atan2(a.edge.dirx, a.edge.dirz);
    let dh=th-a.h; dh=Math.atan2(Math.sin(dh), Math.cos(dh));
    a.h+=dh*Math.min(1, dt*5);
    a.group.rotation.y=a.h;
  }
}

/* ============================== player car ============================== */
const carG=new THREE.Group(); scene.add(carG);
const wheels=[], frontPivots=[];
let playerSpot=null;
function buildPlayerCar(){
  const cm=new THREE.MeshStandardMaterial({color:0xffb020, roughness:.45, metalness:.2});
  const glass=new THREE.MeshStandardMaterial({color:0x22303e, roughness:.25, metalness:.3});
  carG.add(B(boxGeo(3.5,1.1,7.4), cm, 0,1.15,0));
  carG.add(B(boxGeo(3.1,1,3.6), glass, 0,2.15,-.3));
  carG.add(B(boxGeo(3.55,.3,7.45), new THREE.MeshStandardMaterial({color:0x171a24, roughness:.6}), 0,1.35,0));
  for(const sx of [-1,1]) for(const [z,front] of [[2.5,true],[-2.5,false]]){
    const pivot=new THREE.Group(); pivot.position.set(sx*1.6,.65,z);
    const w=B(cylGeo(.65,.65,.5,12), wheelMat, 0,0,0, 0,0,Math.PI/2);
    pivot.add(w); carG.add(pivot);
    wheels.push(w); if(front) frontPivots.push(pivot);
  }
  const hlM=new THREE.MeshStandardMaterial({color:0xfff6d8, emissive:0xfff2b0, emissiveIntensity:0, roughness:.4});
  nightMats.push({m:hlM,k:2.5});
  carG.add(B(boxGeo(.6,.35,.12), hlM, -1.1,1.2,3.72));
  carG.add(B(boxGeo(.6,.35,.12), hlM, 1.1,1.2,3.72));
  const tlM=new THREE.MeshStandardMaterial({color:0x7a1d16, emissive:0xff2b1a, emissiveIntensity:0, roughness:.4});
  nightMats.push({m:tlM,k:1.5});
  carG.add(B(boxGeo(.6,.35,.12), tlM, -1.1,1.2,-3.72));
  carG.add(B(boxGeo(.6,.35,.12), tlM, 1.1,1.2,-3.72));
  playerSpot=new THREE.SpotLight(0xfff2cc, 0, 70, .55, .45, 1.4);
  playerSpot.position.set(0,1.6,3.2);
  playerSpot.target.position.set(0,0,14);
  carG.add(playerSpot, playerSpot.target);
  carG.position.copy(P.pos); carG.rotation.y=P.h;
}
function cornerBlocked(x,z){
  const c=Math.cos(P.h), s=Math.sin(P.h);
  for(const [lx,lz] of [[1.8,3.3],[1.8,-3.3],[-1.8,3.3],[-1.8,-3.3]]){
    const wx=x+s*lx-c*lz, wz=z+c*lx+s*lz;
    if(wx<-209||wx>209||wz<-209||wz>209) return true;
    const e=occ.get(Math.floor(wx/TILE)+','+Math.floor(wz/TILE));
    if(e && e.kind!=='road') return true;
  }
  return false;
}
function isBlocked(x,z){
  if(cornerBlocked(x,z)) return true;
  for(const t of traffic){
    const tp=t.group.position, dx=x-tp.x, dz=z-tp.z;
    if(dx*dx+dz*dz<20) return true;
  }
  return false;
}
function grassAt(x,z){ return !occ.get(Math.floor(x/TILE)+','+Math.floor(z/TILE)); }

const keys={};
function updatePlayer(dt){
  const up=keys.KeyW||keys.ArrowUp, dn=keys.KeyS||keys.ArrowDown;
  const lf=keys.KeyA||keys.ArrowLeft, rt=keys.KeyD||keys.ArrowRight;
  const maxF=P.onGrass?13:34;
  let throttle=0;
  if(up){ P.v+=26*dt; throttle=1; }
  if(dn){ P.v-=(P.v>1?42:20)*dt; throttle=-1; }
  if(!up&&!dn) P.v-=P.v*Math.min(1,dt*1.1);
  if(keys.Space) P.v-=P.v*Math.min(1,dt*4.5);
  P.v=THREE.MathUtils.clamp(P.v, -12, maxF);
  if(Math.abs(P.v)<.05 && !up && !dn) P.v=0;
  const s=(rt?1:0)-(lf?1:0);
  P.h += s*2.6*Math.min(1,Math.abs(P.v)/9)*(P.v<0?-1:1)*dt;
  const nx=P.pos.x+Math.sin(P.h)*P.v*dt;
  const nz=P.pos.z+Math.cos(P.h)*P.v*dt;
  if(!isBlocked(nx,nz)){ P.pos.x=nx; P.pos.z=nz; } else P.v*=-.3;
  P.onGrass=grassAt(P.pos.x,P.pos.z);
  carG.position.copy(P.pos); carG.rotation.y=P.h;
  const spin=P.v*dt/.65;
  wheels.forEach(w=>w.rotation.x+=spin);
  carG.userData.st=THREE.MathUtils.lerp(carG.userData.st||0, s*.5, Math.min(1,dt*8));
  frontPivots.forEach(p=>p.rotation.y=carG.userData.st);
  if(P.onGrass && Math.abs(P.v)>9 && Math.random()<.5)
    puff(P.pos.x-Math.sin(P.h)*3, P.pos.z-Math.cos(P.h)*3, false, .5);
  spdVal.textContent=Math.round(Math.abs(P.v)*3.6);
  spdBar.style.width=(Math.abs(P.v)/34*100)+'%';
}

/* ============================== particles ============================== */
function makePuffTex(){
  const cv=document.createElement('canvas'); cv.width=cv.height=64;
  const g=cv.getContext('2d');
  const gr=g.createRadialGradient(32,32,2,32,32,32);
  gr.addColorStop(0,'rgba(255,255,255,1)'); gr.addColorStop(1,'rgba(255,255,255,0)');
  g.fillStyle=gr; g.fillRect(0,0,64,64);
  return new THREE.CanvasTexture(cv);
}
const puffTex=makePuffTex();
const parts=[];
for(let i=0;i<60;i++){
  const s=new THREE.Sprite(new THREE.SpriteMaterial({map:puffTex, color:0xffffff, transparent:true, opacity:0, depthWrite:false}));
  s.visible=false; scene.add(s);
  parts.push({s, life:0, vel:new THREE.Vector3()});
}
function puff(x,z,big=false,scale=1){
  const n=big?10:4;
  for(let i=0;i<n;i++){
    const p=parts.find(p=>p.life<=0);
    if(!p) break;
    p.life=rand(.45,.75);
    p.s.visible=true;
    p.s.position.set(x+rand(-3,3), .5, z+rand(-3,3));
    p.vel.set(rand(-4,4), rand(3,8), rand(-4,4));
    p.s.material.color.set(big?0xc9b8a0:0xe8e4d8);
    p.s.scale.setScalar(1*scale);
  }
}

